import math
import re
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
_cuda_src = r'''
#include <cuda.h>
#include <cuda_runtime.h>
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#define BLOCK_W 8
#define BLOCK_H 8
#define OC_T 2  // number of output channels computed per block to reuse input tiles
__global__ void conv2d_forward_kernel_tiled(const float* __restrict__ x,
                                            const float* __restrict__ w,
                                            const float* __restrict__ b,
                                            float* __restrict__ y,
                                            int N, int C, int H, int W,
                                            int OC, int KH, int KW,
                                            int pad_h, int pad_w,
                                            int stride_h, int stride_w,
                                            int OH, int OW) {
    extern __shared__ float smem[];
    const int tile_oh = BLOCK_H;
    const int tile_ow = BLOCK_W;
    const int in_tile_h = tile_oh * stride_h + (KH - 1);
    const int in_tile_w = tile_ow * stride_w + (KW - 1);
    float* sX = smem;
    float* sW = sX + in_tile_h * in_tile_w;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tile_ow_idx = blockIdx.x;
    int tile_oh_idx = blockIdx.y;
    // Group multiple output channels per block to reuse input shared-memory tile
    int tiles_oc = (OC + OC_T - 1) / OC_T;
    int z = blockIdx.z;
    int n = z / tiles_oc;
    int oc_group = z % tiles_oc;
    int oc_start = oc_group * OC_T;
    int oc_count = OC - oc_start;
    if (oc_count > OC_T) oc_count = OC_T;
    int oh0 = tile_oh_idx * tile_oh;
    int ow0 = tile_ow_idx * tile_ow;
    int oh = oh0 + ty;
    int ow = ow0 + tx;
    float acc[OC_T];
    #pragma unroll
    for (int i = 0; i < OC_T; ++i) {
        if (i < oc_count) {
            acc[i] = (b != nullptr) ? b[oc_start + i] : 0.0f;
        } else {
            acc[i] = 0.0f;
        }
    }
    int base_ih = oh0 * stride_h - pad_h;
    int base_iw = ow0 * stride_w - pad_w;
    // Loop over input channels
    for (int c = 0; c < C; ++c) {
        // Cooperative load of input tile for channel c into shared memory
        int t = ty * blockDim.x + tx;
        int numel = in_tile_h * in_tile_w;
        const float* x_ptr = x + (((long)n * C + c) * H) * W;
        for (int idx = t; idx < numel; idx += blockDim.x * blockDim.y) {
            int ih_off = idx / in_tile_w;
            int iw_off = idx % in_tile_w;
            int ih = base_ih + ih_off;
            int iw = base_iw + iw_off;
            float val = 0.0f;
            if ((unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)W) {
                val = x_ptr[(long)ih * W + iw];
            }
            sX[idx] = val;
        }
        __syncthreads();
        // For each output channel in this group, load weights and compute using the same sX tile
        for (int oc_off = 0; oc_off < oc_count; ++oc_off) {
            int oc = oc_start + oc_off;
            const float* w_ptr = w + (((long)oc * C + c) * KH) * KW;
            int wnumel = KH * KW;
            for (int idx = t; idx < wnumel; idx += blockDim.x * blockDim.y) {
                sW[idx] = w_ptr[idx];
            }
            __syncthreads();
            if (oh < OH && ow < OW) {
                int ih_off0 = ty * stride_h;
                int iw_off0 = tx * stride_w;
                float sum = 0.0f;
                #pragma unroll 1
                for (int kh = 0; kh < KH; ++kh) {
                    int sRow = ih_off0 + kh;
                    int w_kh_offset = kh * KW;
                    #pragma unroll 1
                    for (int kw = 0; kw < KW; ++kw) {
                        int sCol = iw_off0 + kw;
                        float xv = sX[sRow * in_tile_w + sCol];
                        float wv = sW[w_kh_offset + kw];
                        sum += xv * wv;
                    }
                }
                acc[oc_off] += sum;
            }
            __syncthreads();  // ensure sW is not read before being reloaded for next oc_off
        }
    }
    if (oh < OH && ow < OW) {
        for (int oc_off = 0; oc_off < oc_count; ++oc_off) {
            int oc = oc_start + oc_off;
            long y_idx = (((long)n * OC + oc) * OH + oh) * OW + ow;
            y[y_idx] = acc[oc_off];
        }
    }
}
__global__ void conv2d_forward_kernel_tiled_k11(const float* __restrict__ x,
                                                 const float* __restrict__ w,
                                                 const float* __restrict__ b,
                                                 float* __restrict__ y,
                                                 int N, int C, int H, int W,
                                                 int OC, int KH, int KW,
                                                 int pad_h, int pad_w,
                                                 int stride_h, int stride_w,
                                                 int OH, int OW) {
