    int oc_group = z % tiles_oc;
    int oc_start = oc_group * OC_T;
    int oc_count = OC - oc_start;
    if (oc_count > OC_T) oc_count = OC_T;
    int oh0 = tile_oh_idx * tile_oh;
    int ow0 = tile_ow_idx * tile_ow;
    int oh = oh0 + ty;
    int ow = ow0 + tx;
    float acc[OC_T];
    #pragma unroll
    for (int i = 0; i < OC_T; ++i) {
        if (i < oc_count) {
            acc[i] = (b != nullptr) ? b[oc_start + i] : 0.0f;
        } else {
            acc[i] = 0.0f;
        }
    }
    int base_ih = oh0 * stride_h - pad_h;
    int base_iw = ow0 * stride_w - pad_w;
    for (int c = 0; c < C; ++c) {
        int t = ty * blockDim.x + tx;
        int numel = in_tile_h * in_tile_w;
        const float* x_ptr = x + (((long)n * C + c) * H) * W;
        for (int idx = t; idx < numel; idx += blockDim.x * blockDim.y) {
            int ih_off = idx / in_tile_w;
            int iw_off = idx % in_tile_w;
            int ih = base_ih + ih_off;
            int iw = base_iw + iw_off;
            float val = 0.0f;
            if ((unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)W) {
                val = x_ptr[(long)ih * W + iw];
            }
            sX[idx] = val;
        }
        __syncthreads();
        for (int oc_off = 0; oc_off < oc_count; ++oc_off) {
            int oc = oc_start + oc_off;
            const float* w_ptr = w + (((long)oc * C + c) * 11) * 11;
            int wnumel = 11 * 11;
            for (int idx = t; idx < wnumel; idx += blockDim.x * blockDim.y) {
                sW[idx] = w_ptr[idx];
            }
            __syncthreads();
            if (oh < OH && ow < OW) {
                int ih_off0 = ty * stride_h;
                int iw_off0 = tx * stride_w;
                float sum = 0.0f;
                #pragma unroll
                for (int kh = 0; kh < 11; ++kh) {
                    int sRow = ih_off0 + kh;
                    int w_kh_offset = kh * 11;
                    #pragma unroll
                    for (int kw = 0; kw < 11; ++kw) {
                        int sCol = iw_off0 + kw;
                        float xv = sX[sRow * in_tile_w + sCol];
                        float wv = sW[w_kh_offset + kw];
                        sum += xv * wv;
                    }
                }
                acc[oc_off] += sum;
            }
            __syncthreads();
        }
    }
    if (oh < OH && ow < OW) {
        for (int oc_off = 0; oc_off < oc_count; ++oc_off) {
            int oc = oc_start + oc_off;
            long y_idx = (((long)n * OC + oc) * OH + oh) * OW + ow;
            y[y_idx] = acc[oc_off];
        }
    }
}
void conv2d_forward_cuda(torch::Tensor x,
                         torch::Tensor w,
                         c10::optional<torch::Tensor> b_opt,
                         torch::Tensor y,
                         int pad_h, int pad_w,
                         int stride_h, int stride_w) {
    const int N = x.size(0);
    const int C = x.size(1);
    const int H = x.size(2);
    const int W = x.size(3);
    const int OC = w.size(0);
    const int KH = w.size(2);
    const int KW = w.size(3);
    const int OH = y.size(2);
    const int OW = y.size(3);
    const float* b_ptr = nullptr;
    if (b_opt.has_value()) {
        b_ptr = b_opt.value().data_ptr<float>();
    }
    dim3 block(BLOCK_W, BLOCK_H, 1);
    int tiles_x = (OW + BLOCK_W - 1) / BLOCK_W;
    int tiles_y = (OH + BLOCK_H - 1) / BLOCK_H;
    int tiles_oc = (OC + OC_T - 1) / OC_T;
    dim3 grid(tiles_x, tiles_y, N * tiles_oc);
    int in_tile_h = BLOCK_H * stride_h + (KH - 1);
    int in_tile_w = BLOCK_W * stride_w + (KW - 1);
    size_t smem_bytes = (((size_t)in_tile_h * (size_t)in_tile_w) + ((size_t)KH * (size_t)KW)) * sizeof(float);
    auto stream = at::cuda::getCurrentCUDAStream();
    if (KH == 11 && KW == 11) {
        conv2d_forward_kernel_tiled_k11<<<grid, block, smem_bytes, stream>>>(
            x.data_ptr<float>(),
            w.data_ptr<float>(),
            b_ptr,
            y.data_ptr<float>(),
            N, C, H, W,
            OC, KH, KW,
            pad_h, pad_w,
            stride_h, stride_w,
            OH, OW
        );
    } else {
        conv2d_forward_kernel_tiled<<<grid, block, smem_bytes, stream>>>(
            x.data_ptr<float>(),
            w.data_ptr<float>(),
            b_ptr,
            y.data_ptr<float>(),
            N, C, H, W,
            OC, KH, KW,
            pad_h, pad_w,
            stride_h, stride_w,
            OH, OW
        );
    }
    cudaError_t err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "conv2d_forward_kernel_tiled launch failed: ", cudaGetErrorString(err));
}
'''
# Clean accidental line-number prefixes from the CUDA source that break compilation
_cuda_src = re.sub(r'(?m)^(?:\s*\d+:\s*)+', '', _cuda_src)
_cpp_src = r'''
#include <torch/extension.h>
#include <vector>
// Forward declaration of the CUDA launcher implemented in the .cu file
void conv2d_forward_cuda(torch::Tensor x,
                         torch::Tensor w,
                         c10::optional<torch::Tensor> b_opt,
                         torch::Tensor y,
                         int pad_h, int pad_w,
                         int stride_h, int stride_w);
torch::Tensor conv2d_forward(torch::Tensor x,
                             torch::Tensor w,
                             c10::optional<torch::Tensor> b,
                             int pad_h, int pad_w,
                             int stride_h, int stride_w) {
    TORCH_CHECK(x.is_cuda(), "Input tensor must be CUDA");
    TORCH_CHECK(w.is_cuda(), "Weight tensor must be CUDA");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "Only float32 is supported for input");
    TORCH_CHECK(w.dtype() == torch::kFloat32, "Only float32 is supported for weight");
    if (b.has_value()) {
        TORCH_CHECK(b.value().is_cuda(), "Bias tensor must be CUDA");
        TORCH_CHECK(b.value().dtype() == torch::kFloat32, "Only float32 is supported for bias");
    }
    x = x.contiguous();
    w = w.contiguous();
    const int N = x.size(0);
    const int C = x.size(1);
    const int H = x.size(2);
    const int W = x.size(3);
    const int OC = w.size(0);
    const int KH = w.size(2);
    const int KW = w.size(3);
    TORCH_CHECK(C == w.size(1), "Input channels must match weight's in_channels");
    const int OH = (H + 2 * pad_h - KH) / stride_h + 1;
    const int OW = (W + 2 * pad_w - KW) / stride_w + 1;
    auto y = torch::empty({N, OC, OH, OW}, x.options());
    conv2d_forward_cuda(x, w, b, y, pad_h, pad_w, stride_h, stride_w);
    return y;
}
'''
_custom_conv2d_ext = load_inline(
    name="custom_conv2d_fused_ext",
    cpp_sources=[_cpp_src],
    cuda_sources=[_cuda_src],
    functions=["conv2d_forward"],
    verbose=False
)
class ModelNew(nn.Module):
    def __init__(self, num_classes=1000, in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2, bias=True):
        super(ModelNew, self).__init__()
        if isinstance(kernel_size, tuple):
            kh, kw = kernel_size
        else:
            kh = kw = kernel_size
        if isinstance(stride, tuple):
            sh, sw = stride
        else:
            sh = sw = stride
        if isinstance(padding, tuple):
            ph, pw = padding
        else:
            ph = pw = padding
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = (kh, kw)
        self.stride = (sh, sw)
        self.padding = (ph, pw)
        self.bias_flag = bias
        self.weight = nn.Parameter(torch.empty(out_channels, in_channels, kh, kw))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter('bias', None)
        # Initialize like nn.Conv2d default (Kaiming uniform)
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = in_channels * kh * kw
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure CUDA tensors and float32 dtype
        if not x.is_cuda:
            x = x.cuda()
        if not self.weight.is_cuda:
            self.weight.data = self.weight.data.cuda()
            if self.bias is not None and not self.bias.is_cuda:
                self.bias.data = self.bias.data.cuda()
        if x.dtype != torch.float32:
            x = x.float()
        if self.weight.dtype != torch.float32:
            self.weight.data = self.weight.data.float()
            if self.bias is not None and self.bias.dtype != torch.float32:
                self.bias.data = self.bias.data.float()
        ph, pw = self.padding
        sh, sw = self.stride
        return _custom_conv2d_ext.conv2d_forward(x, self.weight, self.bias, int(ph), int(pw), int(sh), int(sw))

